<?php
require_once 'config/auth.php'; require_once 'config/db.php';
$q=trim($_GET['q']??'');$sql="SELECT Pots.pot_maker AS name,COUNT(*) pot_count,GROUP_CONCAT(DISTINCT Pots.name ORDER BY Pots.name SEPARATOR '||') pot_names,MIN(Pots.id) sample_id,(SELECT p2.contact_info FROM Pots p2 WHERE p2.status='published' AND p2.pot_maker=Pots.pot_maker AND p2.contact_info IS NOT NULL AND p2.contact_info<>'' ORDER BY p2.id DESC LIMIT 1) AS contact_info FROM Pots WHERE Pots.status='published' AND Pots.pot_maker IS NOT NULL AND Pots.pot_maker<>''";$args=[];if($q!==''){$sql.=" AND (Pots.pot_maker LIKE ? OR Pots.name LIKE ? OR Pots.materials LIKE ?)";$args=['%'.$q.'%','%'.$q.'%','%'.$q.'%'];}$sql.=" GROUP BY pot_maker ORDER BY pot_maker";$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$title='Artisan Profiles';include 'partials/header.php';?>
<div class="dashboard-head"><div><span class="eyebrow">ARTISAN KNOWLEDGE</span><h1>Pot Maker Profiles</h1><p>Profiles are assembled from published pottery records and seller contact information.</p></div></div><section class="card"><form method="get" class="inline-form"><input class="input" name="q" value="<?=e($q)?>" placeholder="Search artisan or pottery"><button class="btn small">Search</button></form></section><div class="grid2"><?php foreach($rows as $a):?><article class="card artisan-profile-card"><div class="artisan-profile-thumb"><?php $thumb=$pdo->prepare("SELECT image_path,name FROM Pots WHERE status='published' AND pot_maker=? AND image_path IS NOT NULL AND image_path<>'' ORDER BY id DESC LIMIT 1"); $thumb->execute([$a['name']]); $artisanThumb=$thumb->fetch(); ?><?php if($artisanThumb): ?><img src="<?=e(media_url($artisanThumb['image_path']))?>" alt="<?=e($artisanThumb['name'])?>" loading="lazy"><?php else: ?><span>🏺</span><?php endif; ?></div><span class="badge">Documented Pot Maker</span><h2><?=e($a['name'])?></h2><p><b>Published pottery records:</b> <?=e($a['pot_count'])?></p><?php $artisanPhone=trim((string)($a['contact_info']??'')); $artisanDigits=preg_replace('/[^0-9+]/','',$artisanPhone); if($artisanPhone!=='' && preg_match('/^[+0-9() .-]{7,}$/',$artisanPhone)): ?><p class="artisan-phone-line"><b>Contact Number:</b> <?=e($artisanPhone)?></p><a class="btn small" href="tel:<?=e($artisanDigits)?>">☎ Call Artisan</a><?php else: ?><p class="muted artisan-phone-line">Contact number not provided.</p><?php endif; ?><p class="muted"><?=e(str_replace('||',', ',mb_strimwidth($a['pot_names'],0,220,'…')))?></p><a class="btn small" href="artisan_profile.php?name=<?=urlencode($a['name'])?>">View Profile →</a></article><?php endforeach;?></div><?php if(!$rows):?><div class="empty">No published artisan records found.</div><?php endif;?><?php include 'partials/footer.php';?>